<template><div class="shell"><aside class="sidebar"><div class="side-brand">公益<span>咨询平台</span></div><router-link class="nav-link" to="/dashboard">▦ <span>返回工作台</span></router-link></aside><main class="main"><header class="topbar"><span>{{ title }}</span><el-button type="text" @click="$router.push('/dashboard')">返回工作台</el-button></header><section class="content"><h1 class="page-title">{{ title }}</h1><p class="muted">{{ description }}</p>
  <div v-if="$route.params.module==='appointments'" class="card" style="margin-top:22px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px"><b>预约记录</b><el-button v-if="role==='USER'" type="primary" size="small" @click="dialog=true">预约教授</el-button></div>
    <el-table :data="rows" stripe><el-table-column prop="appointmentNo" label="预约编号" min-width="170"/><el-table-column prop="subject" label="咨询主题" min-width="150"/><el-table-column :prop="role==='PROFESSOR'?'studentName':'professorName'" :label="role==='PROFESSOR'?'预约学生':'咨询教授'"/><el-table-column prop="consultationType" label="咨询类型"/><el-table-column prop="appointmentTime" label="预约时间" min-width="160"/><el-table-column prop="status" label="状态"><template slot-scope="s"><el-tag size="small">{{s.row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template slot-scope="s"><el-button v-if="role==='USER'&&s.row.status==='待确认'" type="text" @click="cancel(s.row.id)">取消预约</el-button><template v-if="role==='PROFESSOR'&&s.row.status==='待确认'"><el-button type="text" @click="decide(s.row,true)">接受</el-button><el-button type="text" style="color:#e06c75" @click="decide(s.row,false)">拒绝</el-button></template></template></el-table-column></el-table>
  </div><div v-else class="card"><el-empty description="该业务模块的接口仍在开发中，当前没有提供虚假的演示操作" /></div>
</section></main>
<el-dialog title="提交教授预约" :visible.sync="dialog" width="520px"><el-form :model="form" label-width="90px"><el-form-item label="教授用户ID"><el-input-number v-model="form.professorId" :min="1"/></el-form-item><el-form-item label="咨询类型"><el-select v-model="form.type" style="width:100%"><el-option label="学业指导" value="学业指导"/><el-option label="升学规划" value="升学规划"/><el-option label="职业发展" value="职业发展"/><el-option label="其他咨询" value="其他咨询"/></el-select></el-form-item><el-form-item label="咨询主题"><el-input v-model="form.subject"/></el-form-item><el-form-item label="咨询内容"><el-input v-model="form.content" type="textarea" :rows="4"/></el-form-item><el-form-item label="预约时间"><el-date-picker v-model="form.time" type="datetime" value-format="yyyy-MM-ddTHH:mm:ss" style="width:100%"/></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">提交预约</el-button></span></el-dialog>
</div></template>
<script>
import {getAppointments,createAppointment,cancelAppointment,decideAppointment} from '../api/appointments'
const names={professors:'教授咨询',appointments:'预约管理',resources:'学习资源',plans:'学习计划',community:'学习社区',questions:'学习问答',messages:'消息通知',schedule:'日程管理',consultations:'咨询记录',evaluations:'评价管理',users:'用户管理',articles:'新闻公告',banners:'轮播图管理',roles:'角色权限',logs:'操作日志'}
export default {data:()=>({rows:[],dialog:false,role:JSON.parse(localStorage.getItem('platform_user')||'{}').role,form:{professorId:1,type:'学业指导',subject:'',content:'',time:''}}),computed:{title(){return names[this.$route.params.module]||'业务模块'},description(){return `这里是${this.title}业务页面。`}},watch:{'$route.params.module':'load'},mounted(){this.load()},methods:{async load(){if(this.$route.params.module==='appointments')this.rows=await getAppointments()},async submit(){if(!this.form.subject||!this.form.content||!this.form.time)return this.$message.warning('请完整填写预约信息');await createAppointment(this.form);this.dialog=false;this.$message.success('预约已提交');this.load()},async cancel(rowId){await cancelAppointment(rowId);this.$message.success('预约已取消');this.load()},async decide(row,accept){await decideAppointment(row.id,{accept,reply:''});this.$message.success('预约处理完成');this.load()}}}
</script>
